O("n605248667", "מזרקת פומוקל", "Pumucklbrunnen", 48.171731, 11.567554, "מזרקה", ["fnt", "ppl"],
  "מזרקה בפארק לויטפולד שמוקדשת לפומוקל, השדון הג'ינג'י והשובב שהוא אחת הדמויות האהובות בספרות הילדים הגרמנית, ונחשב לבן מינכן.",
  "בפארק לויטפולד בשוואבינג, כ-210 מטרים מבית במברג (Bamberger Haus).",
  "פומוקל הוא קובולד, שדון קטן ובלתי נראה שנדבק לסדנה של הנגר מייסטר אדר במינכן. את הדמות יצרה הסופרת אליס קאוט בתחילת שנות ה-60, תחילה בתסכיתי רדיו, ובהמשך בספרים ובסדרת טלוויזיה ששילבה שחקנים ודמות מצוירת. המראה המוכר שלו, השיער האדום והחולצה הצהובה, עוצב על ידי המאיירת ברברה פון ג'ונסון.\nב-OSM אין פרטים על האמן ועל שנת הקמת המזרקה.",
  "",
  ["פומוקל נוצר בידי הסופרת אליס קאוט.", "לפי OSM, המים במזרקה אינם מי שתייה."],
  "משלבים עם האובליסק בפארק ועם בית במברג. מתאים לעצירה עם ילדים.", w=1, yr="", by="", s=6.9,
  kids="פומוקל הוא שדון קטן עם שיער אדום שאוהב לעשות שטויות ולהתחבא. אפשר לחפש אותו במזרקה."),

O("n293903566", "פרח ההריסות", "Schuttblume", 48.170844, 11.556105, "אנדרטה", ["h2"],
  "פסל ברונזה משנת 1972 בצורת פרח, שהוא אנדרטה לקורבנות האזרחיים של מלחמת האוויר, ההפצצות על מינכן במלחמת העולם השנייה. שמו, 'פרח ההריסות', קשור להריסות שמהן נבנתה הגבעה הסמוכה.",
  "באולימפיה פארק, ממזרח לאולימפיאברג, כ-320 מטרים מסי לייף מינכן, לפי הנקודה שבמפה.",
  "במלחמת העולם השנייה הופצצה מינכן פעמים רבות, וחלקים גדולים מהעיר נהרסו. אחרי המלחמה הובאו הריסות הבניינים אל שטח האוברוויזנפלד, ומהן נוצרה גבעה מלאכותית. על השטח הזה נבנה לקראת 1972 האולימפיה פארק, וגבעת ההריסות הפכה לאולימפיאברג.\nלפי OSM הפסל הוצב ב-1972, והוא מוקדש לאזרחים שנהרגו בהפצצות. הצבתו כאן מחברת את הפארק החגיגי עם החומר שממנו נבנה.",
  "",
  ["האולימפיאברג נבנה מהריסות ההפצצות על מינכן.", "לפי OSM: ברונזה, 1972."],
  "משלבים עם עלייה לאולימפיאברג, ממנו נשקף נוף על העיר ועל האלפים ביום בהיר.", w=1, yr="1972", by=""),

